INSERT OR IGNORE INTO vocab_sets (id,name,slug,description,level_id,position,active,word_count,teacher_id,created_at,updated_at) VALUES ('vs-ngsl-01','Common English Words 1–500','common-words-1-500','500 từ tiếng Anh xuất hiện nhiều nhất — học đầu tiên, vì chúng chiếm phần lớn mọi câu nói và bài đọc. Danh sách từ: New General Service List — C. Browne, B. Culligan, J. Phillips (newgeneralservicelist.com), CC BY-SA 4.0.','e6e58a5e-6705-436a-8a26-e608393fc6de',0,1,500,NULL,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-47d07d16381792914e44','vs-ngsl-01',NULL,'the','the','det','ðə','(mạo từ xác định, đặt trước danh từ đã biết)','Close the door, please.',NULL,NULL,'used before a noun to talk about a specific thing that both speaker and listener know about','Làm ơn đóng cửa lại.','A1',NULL,NULL,NULL,NULL,0,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-714045f6c795a10f4b73','vs-ngsl-01',NULL,'be','be','v','biː','là; thì (dùng nối chủ ngữ với tính từ/danh từ bổ nghĩa)','My sister is a nurse.',NULL,NULL,'used to say what someone or something is, or to describe a state or quality','Chị gái tôi là y tá.','A1','["be honest","be careful","be quiet","be right"]',NULL,NULL,NULL,1,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-931ba61ea525b66a13d8','vs-ngsl-01',NULL,'and','and','conj','ænd','và','I like tea and coffee.',NULL,NULL,'used to connect words, phrases, or clauses','Tôi thích trà và cà phê.','A1',NULL,NULL,NULL,NULL,2,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-37e59665d712ca815b1a','vs-ngsl-01',NULL,'of','of','prep','əv','của (chỉ sự sở hữu, liên quan, một phần)','He is a friend of mine.',NULL,NULL,'used to show that one thing belongs to, is part of, or is connected with another','Anh ấy là bạn của tôi.','A1','["a lot of","made of","kind of"]',NULL,NULL,NULL,3,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-540ee6651bb1cd9e2716','vs-ngsl-01',NULL,'to','to','prep','tuː','đến, tới, cho (chỉ hướng, đích, hoặc mục đích)','I''m going to school now.',NULL,NULL,'used to show direction, destination, or the person that receives something','Bây giờ tôi đang đến trường.','A1',NULL,NULL,NULL,NULL,4,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-df7708982d60a0291c65','vs-ngsl-01',NULL,'a','a','det','ə','một (mạo từ không xác định, đứng trước danh từ đếm được số ít)','I saw a dog in the park.',NULL,NULL,'used before a singular countable noun to talk about one person or thing that is not specific','Tôi thấy một con chó trong công viên.','A1',NULL,NULL,NULL,NULL,5,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-220506f459743a408d0b','vs-ngsl-01',NULL,'in','in','prep','ɪn','trong, ở trong, vào (chỉ vị trí hoặc thời gian)','She was born in 2010.',NULL,NULL,'inside a place, area, or period of time','Cô ấy sinh năm 2010.','A1','["in the morning","in 2020","in the box"]',NULL,NULL,NULL,6,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-acc579e1fb5759149a34','vs-ngsl-01',NULL,'have','have','v','hæv','có (sở hữu)','I have two brothers.',NULL,NULL,'to possess or own something','Tôi có hai anh trai.','A1','["have breakfast","have a shower","have fun","have a good time"]',NULL,NULL,NULL,7,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-9ec87782703f0784befe','vs-ngsl-01',NULL,'it','it','pron','ɪt','nó (dùng thay cho vật, con vật, hoặc sự việc đã nhắc tới, hoặc trong câu không có chủ ngữ thật)','It''s raining outside.',NULL,NULL,'used to refer to a thing, animal, or situation already mentioned, or as a dummy subject in sentences about time/weather','Trời đang mưa.','A1','["it is","it''s raining","it seems"]',NULL,NULL,NULL,8,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-da613786e63dbe5f9710','vs-ngsl-01',NULL,'you','you','pron','juː','bạn, anh, chị, các bạn (ngôi thứ hai, chỉ người đang nói chuyện cùng)','You are my best friend.',NULL,NULL,'used to refer to the person or people that someone is speaking or writing to','Bạn là người bạn thân nhất của tôi.','A1',NULL,NULL,NULL,NULL,9,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-c36c48f5f7b1c3ca7661','vs-ngsl-01',NULL,'he','he','pron','hiː','anh ấy, ông ấy, nó (chỉ người/con vật giống đực đã được nhắc tới)','He is my brother.',NULL,NULL,'used to refer to a man, boy, or male animal that has already been mentioned','Anh ấy là anh trai của tôi.','A1',NULL,NULL,NULL,NULL,10,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-93fcd7c736f6577679c7','vs-ngsl-01',NULL,'for','for','prep','fɔːr','cho; dành cho; vì (mục đích, đối tượng)','This gift is for you.',NULL,NULL,'used to show who or what something is intended for, or the purpose/reason of something','Món quà này là dành cho bạn.','A1','["for example","for a while","for sale"]',NULL,NULL,NULL,11,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-dbeb3bb8ddb041757a12','vs-ngsl-01',NULL,'they','they','pron','ðeɪ','họ, chúng (chủ ngữ)','They live in Ha Noi.',NULL,NULL,'used to refer to people or things already mentioned, as the subject of a verb','Họ sống ở Hà Nội.','A1',NULL,NULL,NULL,NULL,12,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-5cbed4c83cc22c9340cb','vs-ngsl-01',NULL,'not','not','adv','nɑːt','không (từ phủ định)','I am not hungry.',NULL,NULL,'used to make a word, sentence, or phrase negative','Tôi không đói.','A1','["not at all","not yet","not only"]',NULL,NULL,NULL,13,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-61ae7b9c38b1c438fba2','vs-ngsl-01',NULL,'that','that','det','ðæt','đó, kia, ấy','Can you pass me that book?',NULL,NULL,'used to refer to a person or thing that is not close to the speaker','Bạn đưa giúp tôi quyển sách kia được không?','A1','["that one","like that","that way"]',NULL,NULL,NULL,14,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-ec9cdf38a702598844fe','vs-ngsl-01',NULL,'we','we','pron','wiː','chúng tôi, chúng ta','We live in Hanoi.',NULL,NULL,'used to refer to the speaker and one or more other people','Chúng tôi sống ở Hà Nội.','A1',NULL,NULL,NULL,NULL,15,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-6868f6ded6b23b182f4b','vs-ngsl-01',NULL,'on','on','prep','ɑːn','trên, ở trên (bề mặt)','The book is on the table.',NULL,NULL,'touching or covering the surface of something','Quyển sách ở trên bàn.','A1','["on the table","on the wall","on the floor"]',NULL,NULL,NULL,16,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-dc7b04066e57d412a248','vs-ngsl-01',NULL,'with','with','prep','wɪð','với, cùng với','I live with my parents.',NULL,NULL,'in the company of another person or thing','Tôi sống cùng với bố mẹ.','A1',NULL,NULL,'["without"]',NULL,17,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-7791f098a83839051ed2','vs-ngsl-01',NULL,'this','this','det','ðɪs','này (chỉ vật/người ở gần)','I like this song a lot.',NULL,NULL,'used to talk about a person, thing, or idea that is nearby or being discussed now','Tôi rất thích bài hát này.','A1',NULL,NULL,NULL,NULL,18,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
