INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-ebaa36544a1b9c1447f5','vs-ngsl-01',NULL,'do','do','v','duː','làm, thực hiện','She does the shopping every Saturday.','["perform","carry out"]',NULL,'to perform an action or activity','Cô ấy đi mua sắm mỗi thứ Bảy.','A1','["do homework","do the shopping","do a favor","do business"]',NULL,NULL,NULL,20,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-baf532f51c4fd394c051','vs-ngsl-01',NULL,'as','as','adv','æz','cũng, bằng (dùng trong so sánh ngang bằng)','He is as tall as his father.',NULL,NULL,'used with another "as" to compare two things or people that are equal in some way.','Anh ấy cao bằng bố mình.','A1','["as...as","just as","as much as"]',NULL,NULL,NULL,21,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
