INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-86659015f20366251509','vs-ngsl-01',NULL,'but','but','conj','bʌt','nhưng','She is small but very strong.',NULL,NULL,'used to introduce a word or phrase that contrasts with what has just been said','Cô ấy nhỏ con nhưng rất khỏe.','A1',NULL,NULL,NULL,NULL,24,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-99fa70d211349b167bbb','vs-ngsl-01',NULL,'from','from','prep','frʌm','từ (nơi chốn, thời điểm, nguồn gốc)','I am from Vietnam.',NULL,NULL,'used to show the place, time, or person that something starts or comes from','Tôi đến từ Việt Nam.','A1','["from now on","from time to time","come from","far from"]',NULL,NULL,NULL,25,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
