INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-419d838fb0425923b357','vs-ngsl-01',NULL,'will','will','v','wɪl','sẽ (trợ động từ chỉ tương lai)','I will call you tomorrow.',NULL,NULL,'used to talk about what is going to happen in the future','Tôi sẽ gọi cho bạn vào ngày mai.','A1',NULL,'["willing (adj)","willingly (adv)"]',NULL,NULL,27,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-a67e651f0d7677989e35','vs-ngsl-01',NULL,'or','or','conj','ɔːr','hoặc, hay','Do you want tea or coffee?',NULL,NULL,'used to connect two or more possible things, choices, or situations','Bạn muốn uống trà hay cà phê?','A1','["either... or","or so","or else"]',NULL,NULL,NULL,28,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-5a73fd2b82ab00e73231','vs-ngsl-01',NULL,'say','say','v','seɪ','nói, phát biểu','What did you say?','["state"]',NULL,'to express a thought, feeling, or fact using words','Bạn vừa nói gì vậy?','A1','["say something","say hello","that is to say","needless to say"]',NULL,NULL,NULL,29,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-caf10ee3939fbbe12b97','vs-ngsl-01',NULL,'go','go','v','ɡoʊ','đi, đi đến','Let''s go to the park.',NULL,NULL,'to move or travel to a place','Chúng ta đi công viên nhé.','A1','["go home","go shopping","go to bed","go out"]',NULL,NULL,NULL,30,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-746a444c50edf7bcc1ab','vs-ngsl-01',NULL,'so','so','adv','soʊ','đến thế, quá, như vậy','I am so tired today.','["very","extremely"]',NULL,'to a great degree; very','Hôm nay tôi mệt quá.','A1','["so much","so many","so far","so that"]',NULL,NULL,NULL,31,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
