INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-a8eee69b514c31bef632','vs-ngsl-04',NULL,'afford','afford','v','əˈfɔːrd','đủ khả năng (về tiền bạc hoặc thời gian) để làm gì','We can''t afford a new car this year.',NULL,NULL,'to have enough money or time to be able to do something','Năm nay chúng tôi không đủ tiền mua xe mới.','B1','["can afford","afford to do something","can''t afford"]','["affordable (adj)","affordability (n)"]',NULL,NULL,487,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
