INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-72a0a6fab6b5eae88f12','vs-ngsl-04',NULL,'suspect','suspect','n','səˈspɛkt','nghi phạm, kẻ tình nghi','Because his fingerprints were found on the weapon, he immediately became the prime suspect.',NULL,NULL,'a person believed to be guilty of a crime or offence','Vì dấu vân tay của anh ta được tìm thấy trên hung khí, anh ta ngay lập tức trở thành nghi phạm chính.','B1','["prime suspect","chief suspect","arrest a suspect"]',NULL,NULL,NULL,489,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
