INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-4b316a7a4cff64fdc6e9','vs-ngsl-04',NULL,'confidence','confidence','n','ˈkɑːnfɪdəns','sự tự tin; lòng tin, sự tin tưởng','Winning the competition gave her a lot of confidence.',NULL,NULL,'a feeling of trust in one''s own abilities, or trust in someone/something','Chiến thắng cuộc thi đã mang lại cho cô ấy rất nhiều sự tự tin.','B1','["gain confidence","have confidence in","self-confidence"]','["confident (adj)","confidently (adv)"]',NULL,NULL,492,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-9735f2084018742cea3a','vs-ngsl-04',NULL,'industrial','industrial','adj','ɪnˈdʌstriəl','thuộc về công nghiệp','The town has several large industrial areas.','["manufacturing"]',NULL,'relating to industry or the people working in it','Thị trấn có một vài khu công nghiệp lớn.','B1','["industrial area","industrial revolution","industrial waste"]','["industry (n)","industrialize (v)","industrialization (n)"]',NULL,NULL,493,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-3a7ec61362a3a035187c','vs-ngsl-04',NULL,'complain','complain','v','kəmˈpleɪn','phàn nàn, than phiền','He''s always complaining about the weather.','["grumble","moan"]',NULL,'to say that you are unhappy or dissatisfied about something','Anh ấy lúc nào cũng than phiền về thời tiết.','A2','["complain about","complain to someone","complain that"]','["complaint (n)"]',NULL,NULL,494,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-7f2787ca80b68c3abe5e','vs-ngsl-04',NULL,'perspective','perspective','n','pərˈspɛktɪv','quan điểm, góc nhìn','Living abroad gave her a completely different perspective on life.','["viewpoint","outlook"]',NULL,'a particular way of thinking about something, especially one influenced by your own experience or beliefs.','Sống ở nước ngoài mang lại cho cô ấy một góc nhìn hoàn toàn khác về cuộc sống.','B2','["from a ... perspective","gain a new perspective","put things into perspective","broaden your perspective"]',NULL,NULL,NULL,495,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
