INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-73616797b9bf22ac7102','vs-ngsl-04',NULL,'arrest','arrest','v','əˈrɛst','bắt giữ (do cảnh sát)','The police arrested two men for robbery.',NULL,NULL,'if the police arrest someone, they take that person to a police station because they may have committed a crime','Cảnh sát đã bắt giữ hai người đàn ông vì tội cướp.','B1','["arrest someone for doing","arrest somebody for something","be arrested"]',NULL,NULL,NULL,497,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-cf25f17575932e3faf77','vs-ngsl-04',NULL,'assess','assess','v','əˈsɛs','đánh giá','Teachers assess students'' progress at the end of each term.','["evaluate","judge"]',NULL,'to judge or decide the amount, value, or quality of something','Giáo viên đánh giá tiến bộ của học sinh vào cuối mỗi kỳ.','B2','["assess the situation","assess the risk","assess performance","assess a student"]','["assessment (n)"]',NULL,NULL,498,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
