INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-55427230df9c6d8da0e9','vs-ngsl-05',NULL,'necessarily','necessarily','adv','ˌnɛsəˈsɛrəli','một cách tất yếu, nhất thiết (thường dùng trong "not necessarily")','Being rich doesn''t necessarily mean being happy.',NULL,NULL,'used, often in negative sentences, to say that something is always true or must happen','Giàu có không nhất thiết đồng nghĩa với hạnh phúc.','B1','["not necessarily","necessarily true"]','["necessary (adj)","necessity (n)"]',NULL,NULL,8,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
