INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-7f8c991c38123539f2ae','vs-ngsl-05',NULL,'slowly','slowly','adv','ˈsloʊli','một cách chậm chạp, chậm rãi','She walked slowly down the street.',NULL,NULL,'at a slow speed; not quickly','Cô ấy đi bộ chậm rãi trên phố.','A2','["walk slowly","speak slowly","move slowly","slowly but surely"]',NULL,'["quickly","fast"]',NULL,11,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
