INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-24a3cc7a55b7e87d3a7c','vs-ngsl-05',NULL,'ear','ear','n','ɪr','tai (bộ phận cơ thể)','He whispered something in my ear.',NULL,NULL,'the part of the body that you use for hearing','Anh ấy thì thầm điều gì đó vào tai tôi.','A1','["an ear infection","have an ear for music"]','["earring (n)"]',NULL,NULL,163,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
