INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-2a69ceedf5cc3ca714f0','vs-ngsl-05',NULL,'significantly','significantly','adv','sɪɡˈnɪfɪkəntli','một cách đáng kể, rõ rệt','Sales have dropped significantly since the store closed its main branch.','["considerably","substantially","markedly"]',NULL,'in a way that is large or important enough to be noticed','Doanh số đã giảm đáng kể kể từ khi cửa hàng đóng chi nhánh chính.','B2','["increase significantly","differ significantly","improve significantly"]','["significant (adj)","significance (n)"]','["slightly","marginally"]',NULL,168,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
