INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-c200637ac9e3e9a7fbcc','vs-ngsl-05',NULL,'personally','personally','adv','ˈpɜːrsənəli','về phần cá nhân (tôi); đích thân','Personally, I don''t agree with the decision.',NULL,NULL,'used to say what your own opinion is, rather than anyone else''s','Về phần tôi, tôi không đồng ý với quyết định đó.','B1','["personally, I"]',NULL,NULL,NULL,398,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
