INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-5affd4dc6db646ce2929','vs-ngsl-05',NULL,'consistent','consistent','adj','kənˈsɪstənt','nhất quán, kiên định, không thay đổi','The results from all three tests were consistent, confirming the theory.','["steady","stable"]',NULL,'always behaving or happening in a similar way, or being of a similar standard','Kết quả của cả ba bài kiểm tra đều nhất quán, xác nhận đúng giả thuyết.','B2','["consistent with","remain consistent","consistent performance"]','["consistency (n)","consist (v)"]','["inconsistent","erratic"]',NULL,441,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
