INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-4e2bdba82b8f32313ca3','vs-ngsl-05',NULL,'hunt','hunt','v','hʌnt','săn (thú), săn bắt; tìm kiếm','Wolves usually hunt in packs to catch larger animals.',NULL,NULL,'to chase and kill wild animals for food or sport, or to search for something','Sói thường săn theo bầy để bắt những con vật lớn hơn.','B1','["hunt for food","hunt down","go hunting"]','["hunter (n)"]',NULL,NULL,497,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-6ebac9c2f366a6278cb6','vs-ngsl-05',NULL,'storm','storm','n','stɔːrm','cơn bão, cơn giông','The storm damaged many houses.','["tempest"]',NULL,'very bad weather with strong wind, heavy rain, and often thunder and lightning','Cơn bão đã làm hư hại nhiều ngôi nhà.','A1','["heavy storm","storm warning","in a storm"]','["stormy (adj)"]',NULL,NULL,498,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
