INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-77dd2bacd958eccf0c84','vs-ngsl-06',NULL,'negotiate','negotiate','v','nɪˈɡoʊʃieɪt','đàm phán, thương lượng','The union negotiated a pay rise with management.','["bargain"]',NULL,'to discuss something with someone in order to reach an agreement','Công đoàn đã đàm phán để tăng lương với ban quản lý.','B1','["negotiate a deal","negotiate with someone","negotiate a contract","negotiate a price"]','["negotiation (n)","negotiator (n)","negotiable (adj)"]',NULL,NULL,1,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-2a1dce04330a2bc883ec','vs-ngsl-06',NULL,'dominate','dominate','v','ˈdɑːməneɪt','thống trị, chi phối, áp đảo','A few large companies dominate the smartphone market.','["control","rule"]',NULL,'to have power or control over someone or something, or to be the most important or noticeable feature','Một vài công ty lớn thống trị thị trường điện thoại thông minh.','B2','["dominate the market","dominate a conversation","dominate the game"]','["dominant (adj)","domination (n)"]',NULL,NULL,2,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
