INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-779b460e1a72b2e9481c','vs-ngsl-06',NULL,'typically','typically','adv','ˈtɪpɪkli','thông thường, thường là, điển hình là','Typically, the meeting starts at 9 a.m.','["usually","generally"]',NULL,'in most cases; used to describe what usually happens or what is normal for a particular type of person, thing, or situation','Thông thường, cuộc họp bắt đầu lúc 9 giờ sáng.','B1','["typically used for","typically found in"]','["typical (adj)","type (n)"]',NULL,NULL,5,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
