INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-b662ed139e57fbd8e70a','vs-ngsl-06',NULL,'respectively','respectively','adv','rɪˈspɛktɪvli','theo thứ tự tương ứng, lần lượt','Tom and Jane scored 90 and 85, respectively.',NULL,NULL,'in the same order as the things or people that have just been mentioned','Tom và Jane lần lượt đạt điểm 90 và 85.','B2',NULL,'["respective (adj)"]',NULL,NULL,17,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
