INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-86bf9aaf403b129a42f6','vs-ngsl-06',NULL,'initially','initially','adv','ɪˈnɪʃəli','ban đầu, lúc đầu','Initially, I didn''t like the job, but now I love it.','["at first","originally"]',NULL,'at the beginning; at first','Ban đầu tôi không thích công việc này, nhưng giờ tôi lại yêu thích nó.','B1','["initially planned","initially thought","but initially"]','["initial (adj)","initiate (v)"]','["finally","eventually"]',NULL,145,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
