INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-c5f886c12d67cee84581','vs-ngsl-06',NULL,'opponent','opponent','n','əˈpoʊnənt','đối thủ, người/phe đối lập','The senator faced strong opponents of his new bill.','["rival","adversary"]',NULL,'a person who competes against you in a game, contest, or argument','Vị thượng nghị sĩ phải đối mặt với những người phản đối mạnh mẽ dự luật mới của mình.','B2','["defeat an opponent","political opponent","tough opponent","face an opponent"]','["oppose (v)","opposition (n)","opposite (adj)"]','["ally","teammate"]',NULL,394,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-0418e388004ca5959ae8','vs-ngsl-06',NULL,'resist','resist','v','rɪˈzɪst','chống lại, kháng cự; cưỡng lại (cám dỗ)','I couldn''t resist buying the chocolate cake.','["withstand","oppose"]',NULL,'to refuse to accept something and try to stop it happening, or to stop yourself from doing something you want to do','Tôi không thể cưỡng lại việc mua chiếc bánh chocolate đó.','B1','["resist temptation","resist the urge to","resist change"]','["resistance (n)","resistant (adj)"]','["yield","surrender"]',NULL,395,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-41f9c0dcb4e806f5e81e','vs-ngsl-06',NULL,'capability','capability','n','ˌkeɪpəˈbɪləti','khả năng, năng lực','She has the capability to lead the whole team.','["ability","capacity"]',NULL,'the ability or power to do something','Cô ấy có năng lực để lãnh đạo cả đội.','B2','["have the capability","military capability","technical capability","beyond one''s capability"]','["capable (adj)","capably (adv)","incapable (adj)"]','["inability"]',NULL,396,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-da9d273a1d771e66909a','vs-ngsl-06',NULL,'absolute','absolute','adj','ˈæbsəluːt','hoàn toàn, tuyệt đối','There was absolute silence in the room.','["complete","total"]',NULL,'total and complete','Căn phòng hoàn toàn im lặng.','B1','["absolute silence","absolute control","absolute confidence"]','["absolutely (adv)"]','["partial","relative"]',NULL,397,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-4094e7c56adefc9a9791','vs-ngsl-06',NULL,'correspond','correspond','v','ˌkɔːrəˈspɑːnd','tương ứng, phù hợp với','Each color on the map corresponds to a different region.','["match","be equivalent to"]',NULL,'to be similar to, match, or be the same as something else','Mỗi màu trên bản đồ tương ứng với một vùng khác nhau.','B2','["correspond with something","correspond to","correspond exactly","closely correspond"]',NULL,NULL,NULL,398,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-3115b0585447104d7209','vs-ngsl-06',NULL,'stroke','stroke','n','stroʊk','cơn đột quỵ, tai biến mạch máu não','High blood pressure increases the risk of stroke.',NULL,NULL,'a sudden loss of brain function caused by an interruption of blood flow to the brain','Huyết áp cao làm tăng nguy cơ đột quỵ.','B2','["have a stroke","suffer a stroke","stroke victim","risk of stroke"]',NULL,NULL,NULL,399,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-045fd878f35bfa56eb96','vs-ngsl-06',NULL,'dare','dare','v','dɛr','dám, đủ can đảm (làm gì)','How dare you say that to me!',NULL,NULL,'to be brave enough to do something risky or difficult','Sao anh dám nói vậy với tôi!','B1','["dare to do something","how dare you","don''t you dare"]','["daring (adj)"]',NULL,NULL,400,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-a86f34388358398c6606','vs-ngsl-06',NULL,'barrier','barrier','n','ˈbɛriər','rào cản, chướng ngại','Language can be a major barrier when traveling abroad.','["obstacle"]',NULL,'something that prevents people from doing something, or that separates two areas','Ngôn ngữ có thể là rào cản lớn khi đi du lịch nước ngoài.','B2','["language barrier","break down barriers","trade barrier"]',NULL,NULL,NULL,401,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-824681be51e8681df3d1','vs-ngsl-06',NULL,'rid','rid','v','rɪd','loại bỏ, làm cho thoát khỏi (thường dùng trong cụm ''get/be rid of'')','We need to get rid of these old newspapers.',NULL,NULL,'to make a person or place free of something unwanted','Chúng ta cần vứt bỏ những tờ báo cũ này.','B1','["get rid of","rid yourself of","well rid of"]','["riddance (n)"]',NULL,NULL,402,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-abe4435628ba5747d694','vs-ngsl-06',NULL,'divorce','divorce','n','dɪˈvɔːrs','sự ly hôn, sự ly dị','They got a divorce after ten years of marriage.',NULL,NULL,'the legal ending of a marriage','Họ ly hôn sau mười năm chung sống.','B1','["get a divorce","file for divorce","divorce rate"]','["divorcee (n)"]',NULL,NULL,403,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-69b9122c13bf21a5afa4','vs-ngsl-06',NULL,'ruin','ruin','v','ˈruːɪn','phá hủy, làm hỏng hoàn toàn','The heavy rain ruined our picnic plans.','["destroy","spoil","wreck"]',NULL,'to severely damage, spoil, or destroy something completely','Cơn mưa lớn đã làm hỏng kế hoạch dã ngoại của chúng tôi.','A2','["ruin someone''s life","ruin a surprise","completely ruined"]','["ruinous (adj)"]',NULL,NULL,404,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_sets (id,name,slug,description,level_id,position,active,word_count,teacher_id,created_at,updated_at) VALUES ('vs-ngsl-07','Common English Words 2406–2809','common-words-2406-2809','Từ 2406 đến 2809 — bộ cuối. Học hết các bộ là hiểu được hơn 9/10 số từ trong một văn bản thông thường. Danh sách từ: New General Service List — C. Browne, B. Culligan, J. Phillips (newgeneralservicelist.com), CC BY-SA 4.0.','470b8ff4-fa97-4ff8-9c6b-902fde8e0d7b',6,1,404,NULL,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
