INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-d35f152eeefa36577099','vs-ngsl-07',NULL,'permission','permission','n','pərˈmɪʃən','sự cho phép','You need permission to enter this area.','["consent"]',NULL,'when someone allows you to do something','Bạn cần được cho phép để vào khu vực này.','A2','["ask for permission","give permission","without permission"]','["permit (v)","permitted (adj)"]',NULL,NULL,8,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
