INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-3c1f70ec841989c9bc9f','vs-ngsl-07',NULL,'mad','mad','adj','mæd','(thông tục) rất tức giận','My mom was mad at me for coming home late.','["furious","angry"]',NULL,'(informal) very angry','Mẹ tôi đã rất tức giận vì tôi về nhà muộn.','A2','["mad at someone","go mad","drive someone mad"]','["madness (n)"]','["calm"]',NULL,11,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-cf701533f9fe7a5ce6dd','vs-ngsl-07',NULL,'greatly','greatly','adv','ˈɡreɪtli','rất nhiều, đáng kể (nhấn mạnh mức độ của động từ/tính từ)','Her health has greatly improved since the treatment.','["significantly","considerably","substantially"]',NULL,'to a large degree; very much','Sức khỏe của cô ấy đã cải thiện đáng kể kể từ khi điều trị.','A2','["greatly improve","greatly appreciate","greatly reduce","greatly increase"]','["great (adj)","greatness (n)"]',NULL,NULL,12,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
