INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-ba391fd9f802cef0d8c2','vs-ngsl-07',NULL,'immigration','immigration','n','ˌɪməˈɡreɪʃən','sự nhập cư (việc chuyển đến sinh sống lâu dài ở một nước khác)','The government introduced new immigration policies.',NULL,NULL,'the process of coming to live permanently in a country that is not your own','Chính phủ đã đưa ra các chính sách nhập cư mới.','B1','["immigration policy","illegal immigration","immigration law","mass immigration"]','["immigrant (n)","immigrate (v)","emigration (n)"]','["emigration"]',NULL,380,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-5ef5436d69d878f56f62','vs-ngsl-07',NULL,'tender','tender','adj','ˈtɛndər','dịu dàng, âu yếm','He spoke in a tender voice to comfort the crying child.','["gentle","loving","affectionate"]',NULL,'showing gentle and caring feelings towards someone','Anh ấy nói bằng giọng dịu dàng để dỗ dành đứa trẻ đang khóc.','B2','["tender voice","tender care","tender moment","loving and tender"]','["tenderness (n)","tenderly (adv)"]','["harsh"]',NULL,381,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-76c1aea714cac3eef944','vs-ngsl-07',NULL,'density','density','n','ˈdɛnsəti','mật độ, khối lượng riêng (vật lý)','Gold has a much higher density than water.',NULL,NULL,'the amount of mass a substance has for a given volume','Vàng có khối lượng riêng cao hơn nhiều so với nước.','B2','["high density","density of a substance"]','["dense (adj)","densely (adv)"]',NULL,NULL,382,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-478102efe1673eb63e33','vs-ngsl-07',NULL,'ugly','ugly','adj','ˈʌɡli','xấu, xấu xí (về ngoại hình)','She thinks she''s ugly, but I think she''s beautiful.','["unattractive","hideous"]',NULL,'unpleasant or unattractive to look at','Cô ấy nghĩ mình xấu, nhưng tôi thấy cô ấy xinh đẹp.','A1','["an ugly building","ugly duckling"]','["ugliness (n)"]','["beautiful","pretty"]',NULL,383,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-a6ab66909acaf669fb62','vs-ngsl-07',NULL,'module','module','n','ˈmɑːdʒuːl','học phần (đơn vị học tập trong một khóa học)','In the second semester, students can choose an optional module on British literature.',NULL,NULL,'a self-contained part of a course of study, taught and often assessed separately','Ở học kỳ hai, sinh viên có thể chọn một học phần tự chọn về văn học Anh.','B2','["an optional module","take a module"]','["modular (adj)"]',NULL,NULL,384,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-3c3f5ae344befe47d276','vs-ngsl-07',NULL,'faithful','faithful','adj','ˈfeɪθfəl','chung thủy, trung thành (với vợ/chồng, bạn bè, lý tưởng)','Despite many temptations, he stayed completely faithful to his wife.','["loyal","devoted"]',NULL,'loyal and continuing to support a person, group, or belief, especially a partner','Dù gặp nhiều cám dỗ, anh vẫn hoàn toàn chung thủy với vợ.','B1','["faithful husband/wife","remain faithful","faithful friend"]','["faith (n)","faithfully (adv)","unfaithful (adj)"]','["unfaithful","disloyal"]',NULL,385,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-9409021431ac2b3f69e7','vs-ngsl-07',NULL,'autumn','autumn','n','ˈɔːtəm','mùa thu','The leaves turn brown in autumn.','["fall"]',NULL,'the season between summer and winter when leaves fall from the trees.','Lá cây chuyển sang màu nâu vào mùa thu.','A1','["in autumn","autumn leaves"]',NULL,NULL,NULL,386,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
