INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-7904de946de4f154cef4','vs-ngsl-07',NULL,'grin','grin','v','ɡrɪn','cười toe toét, cười rạng rỡ','She grinned at the funny joke.',NULL,NULL,'to smile broadly, showing your teeth','Cô ấy cười toe toét trước câu chuyện cười.','B2','["grin from ear to ear","grin with delight"]',NULL,NULL,NULL,391,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
