INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-aa7d3d7373bbbf0b0973','vs-ngsl-07',NULL,'found','found','v','faʊnd','thành lập, sáng lập','The company was founded in 1990.','["establish","set up"]',NULL,'to start an organization, institution, etc. that is intended to last for a long time','Công ty được thành lập vào năm 1990.','A1','["found a company","found an organization","newly founded"]','["founder (n)","foundation (n)","founding (adj)"]',NULL,NULL,401,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-b28e7f84aeadd2aefe40','vs-ngsl-07',NULL,'blog','blog','n','blɑːɡ','blog, nhật ký trực tuyến','She writes a blog about cooking.',NULL,NULL,'a website where someone writes regularly about their own experiences or opinions','Cô ấy viết một blog về nấu ăn.','A1','["write a blog","blog post","personal blog"]',NULL,NULL,NULL,402,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
INSERT OR IGNORE INTO vocab_items (id,set_id,user_id,word,word_key,pos,ipa,meaning,example,synonyms,image,definition,example_vi,cefr,collocations,family,antonyms,note,position,created_at,updated_at) VALUES ('ngsl-85294b9f017280ea91f7','vs-ngsl-07',NULL,'thirst','thirst','n','θɜːrst','cơn khát; (nghĩa bóng) sự khao khát','She has a thirst for knowledge and reads every day.',NULL,NULL,'the feeling of needing or wanting to drink; also used figuratively for a strong desire for something','Cô ấy có khao khát tri thức và đọc sách mỗi ngày.','A2','["quench your thirst","thirst for knowledge","die of thirst"]',NULL,NULL,NULL,403,'2026-10-27T00:00:00.000Z','2026-10-27T00:00:00.000Z');
